def prefix_function(s):
    """前缀函数:pi[i] = s[0..i] 的最长公共真前后缀(border)长度,0 索引。"""
    n = len(s)
    pi = [0] * n
    for i in range(1, n):
        k = pi[i - 1]
        while k > 0 and s[i] != s[k]:
            k = pi[k - 1]          # 失配:回退到更短的 border
        if s[i] == s[k]:
            k += 1
        pi[i] = k
    return pi


def kmp(text, pat):
    """前缀函数主流写法:k = 已匹配的 pat 前缀长度,失配用 k = pi[k-1] 回跳。"""
    m = len(pat)
    if m == 0:
        return 0
    pi = prefix_function(pat)
    k = 0
    for i, ch in enumerate(text):
        while k > 0 and ch != pat[k]:
            k = pi[k - 1]
        if ch == pat[k]:
            k += 1
        if k == m:                 # 配满整个 pat,返回起点
            return i - m + 1
    return -1

def prefix_function(s):
    """前缀函数:pi[i] = s[0..i] 的最长公共真前后缀(border)长度。"""
    n = len(s)
    pi = [0] * n
    for i in range(1, n):
        k = pi[i - 1]
        while k > 0 and s[i] != s[k]:
            k = pi[k - 1]
        if s[i] == s[k]:
            k += 1
        pi[i] = k
    return pi


def kmp(text, pat):
    """统一写法:对 pat + 分隔符 + text 跑一次前缀函数,pi 值 == m 处即匹配末尾。
    分隔符须既不在 text 也不在 pat 中出现,否则 border 可能跨越分隔符导致误判。"""
    m = len(pat)
    if m == 0:
        return 0
    sep = "\x00"
    s = pat + sep + text
    pi = prefix_function(s)
    for i in range(m + 1, len(s)):
        if pi[i] == m:
            return i - 2 * m       # i 是匹配末尾在拼接串中的下标,换算回 text 起点
    return -1
